@startuml

class Bus {
  + LineNumber : string
}

class Trajectory {
  + ApprovalStatus : string
  + OperationalFrom : date
  + IsSuspended : boolean
  + IsCancelled : boolean
}

class Line {
  + Category : string
}

class TownAuthority {
  + Name : string
}

class ApprovalProcess {
  + Status : string
}

class MENSOUser {
  + HomeAddress : string
  + OfficeAddress : string
  + WorkingHours : string
}

class MENSOCard {
  + CardNumber : string
}

class Trip {
  + Date : date
  + Time : time
}

class Invoice {
  + Amount : float
  + Discount : float
}

class Customer {
  + Name : string
}

Bus "0..*" -- "1..*" Trajectory : assigned to
Line "1" -- "1..*" Trajectory : groups
Trajectory "1" -- "0..*" ApprovalProcess : undergoes
TownAuthority "1" -- "0..*" ApprovalProcess : reviews
MENSOUser "1" -- "1" MENSOCard : possesses
MENSOUser "1" -- "0..*" Invoice : receives
MENSOUser "1" -- "0..*" Trip : makes
Line "1" -- "0..*" Trip : is travelled on
Trip "1" -- "1" MENSOCard : uses
Customer "1" -- "0..*" Invoice : pays
Invoice "1" -- "0..*" Trip : includes

@enduml

